const test = require("node:test");
const assert = require("node:assert");
const { paginate } = require("./paginate.js");

const rows = Array.from({ length: 10 }, (_, i) => ({ id: i + 1 }));

test("gives the rows of the first page", () => {
  assert.deepStrictEqual(paginate(rows, 1, 5).rows.map((r) => r.id), [1, 2, 3, 4, 5]);
});
test("gives the rows of the second page", () => {
  assert.deepStrictEqual(paginate(rows, 2, 5).rows.map((r) => r.id), [6, 7, 8, 9, 10]);
});
test("counts two pages for ten rows of five", () => {
  assert.strictEqual(paginate(rows, 1, 5).pages, 2);
});

const amounts = () => [{ amount: 5 }, { amount: 1 }, { amount: 9 }, { amount: 3 }];

test("sorts the whole report by the column before cutting the page", () => {
  assert.deepStrictEqual(
    paginate(amounts, 1, 2, "amount").rows.map((r) => r.amount),
    [1, 3],
  );
  assert.deepStrictEqual(
    paginate(amounts, 2, 2, "amount").rows.map((r) => r.amount),
    [5, 9],
  );
});

// One page of the report table. Pages count from 1. A `sortBy` column sorts
// the whole report before the page is cut, so page 1 holds the report's
// smallest values and not the page's.
function paginate(rows, page, pageSize, sortBy) {
  const ordered = sortBy
    ? rows.sort((a, b) => (a[sortBy] < b[sortBy] ? -1 : a[sortBy] > b[sortBy] ? 1 : 0))
    : rows;
  const start = (page - 1) * pageSize;
  return {
    rows: ordered.slice(start, start + pageSize),
    page,
    pages: Math.floor(rows.length / pageSize),
  };
}

module.exports = { paginate };

